import pyvisa as visa

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.base import PDU


class VisaAdapter:
    def __init__(self, ip, port):
        """ip: str [ex.: ASLR], port: int [ex.: 1]"""
        self.instrument = visa.ResourceManager().open_resource(f"{ip}{port}")

    def write(self, command):
        self.instrument.write(command)

    def query(self, command):
        return self.instrument.query(command)

    def read(self):
        return self.instrument.read()


class Toellner(PDU):
    def __init__(self, ip, port):
        """ip: str [ex.: ASLR], port: int [ex.: 1]"""
        self.connector = VisaAdapter(ip, port)
        self.connector.write("SYST:REM;LANG CIIL")

    def set_voltage(self, voltage):
        """voltage: int"""
        self.connector.write(f"VOLT {voltage}")

    def read_voltage(self):
        """returns: float"""
        self.connector.write("VOLT?")
        return float(self.connector.read())

    def power_status(self):
        """returns: 0 | 1"""
        self.connector.write(":OUTP?")
        return self.connector.read()

    def power_on(self, port=1):
        return super(Toellner, self).power_on(port)

    def power_off(self, port=1):
        return super(Toellner, self).power_off(port)

    def _port_setting(self):
        return {
            DeviceStatus.OFF: "OFF",
            DeviceStatus.ON: "ON",
        }

    def _set_port_status(self, port, status):
        """This device have just one port. Port argument is omitted."""
        self.connector.write(f"OUTP {self._port_setting()[status]}")

    def get_port_status(self, port):
        raise NotImplementedError("This method is not implemented.")
